-- PIPING 8.50 · cobre (EN 1254), cuproníquel 90/10 (EEMUA 145 / 146) y transiciones entre materiales.
-- Ejecutar en Supabase > SQL Editor después de 07_accesorios.sql y 11_accesorios_roscados.sql. Se puede repetir.
begin;
alter table public.piping_acc_materiales drop constraint if exists piping_acc_materiales_familia_check;
alter table public.piping_acc_materiales add constraint piping_acc_materiales_familia_check check (familia in ('Acero al carbono', 'Acero inoxidable', 'Cobre', 'Cuproníquel'));
on conflict (id) do update set cod = excluded.cod, subtipo = excluded.subtipo, tipo = excluded.tipo, variante = excluded.variante, nombre = excluded.nombre, sistema = excluded.sistema, norma = excluded.norma, conexion = excluded.conexion, tipo_crane = excluded.tipo_crane, mat_grupo = excluded.mat_grupo, esp_tabla = excluded.esp_tabla, notas = excluded.notas, orden = excluded.orden, ratings = excluded.ratings, caras = excluded.caras, dn_min = excluded.dn_min, dn_max = excluded.dn_max, activo = true;
on conflict (designacion) do update set codigo = excluded.codigo, familia = excluded.familia, grupo = excluded.grupo, norma = excluded.norma, equivalente = excluded.equivalente, orden = excluded.orden;
commit;
